\label{def:semiprime}
A submodule $N$ of $M$ is \emph{semiprime} if for every $m\in M$,
\[m\in(N:m)M\ \Longrightarrow\ m\in N,\qquad\text{where }(N:m):=\{r\in R:\ rm\in N\}.\]

\label{thmA}
Let $N$ be a submodule of an arbitrary $R$-module $M$. The following are equivalent:
\begin{enumerate}
\item[(i)] $N$ is semiprime;
\item[(ii)] $N=\bigcap_{\mathfrak p\in\operatorname{Spec} R}K(N,\mathfrak p)$, where $K(N,\mathfrak p):=\{m\in M:\ sm\in N+\mathfrak p M\text{ for some }s\notin\mathfrak p\}$;
\item[(iii)] $N$ is an intersection of prime submodules of $M$.
\end{enumerate}
Consequently, the radical of any submodule $N$ is the smallest semiprime submodule of $M$ containing $N$.

\label{thmB}
Let $N$ be a submodule of an arbitrary $R$-module $M$. The following are equivalent:
\begin{enumerate}
\item[(i)] $N$ is real;
\item[(ii)] $N=\bigcap\{K(N,\mathfrak p):\ \mathfrak p\text{ a real prime ideal of }R\}$;
\item[(iii)] $N$ is an intersection of real prime submodules of $M$.
\end{enumerate}
Consequently, the intersection of the real prime submodules containing a submodule $N$ (which is $M$ if there is none; note that $M$ itself is a real submodule, as $M/M=0$) is the smallest real submodule containing $N$; a module is semireal if and only if it has a real prime submodule; and every submodule maximal among the proper real submodules is prime.

\label{lem:basic}
Let $N$ be a submodule of an $R$-module $M$.
\begin{enumerate}
\item[(a)] $N$ is a prime submodule of $M$ if and only if $M/N$ is a prime module; then $(N:M)=\operatorname{Ann}_R(M/N)$ is a prime ideal.
\item[(b)] $N$ is a semiprime submodule of $M$  if and only if $M/N$ is a semiprime module.
\item[(c)] Every prime submodule is semiprime.
\item[(d)] Every intersection of semiprime submodules is semiprime.
\item[(e)] Submodules of semiprime modules are semiprime, and nonzero submodules of prime modules are prime.
\item[(f)] Direct products, and hence direct sums, of semiprime modules are semiprime.
\end{enumerate}

\label{rem:dauns}
Let $N$ be a submodule of an $R$-module $M$.
\begin{enumerate}
\item[(a)] If $N$ is semiprime, then $(N:m)$ is a radical ideal for every $m\in M$. In particular, if $M$ is semiprime, then $\operatorname{Ann}_R(q)$ is radical for every $q\in M$.
\item[(b)] If $R$ is a Dedekind domain and $(N:m)$ is radical for every $m\in M$, then $N$ is semiprime.
\end{enumerate}

\label{lem:Np}
For every submodule $N$ of an $R$-module $M$ and every prime ideal $\mathfrak p$ of $R$, the set
\[K(N,\mathfrak p)=\{m\in M:\ sm\in N+\mathfrak p M\text{ for some }s\notin\mathfrak p\}\]
is a submodule of $M$ containing $N+\mathfrak p M$. Moreover:
\begin{enumerate}
\item[(a)] Either $K(N,\mathfrak p)=M$, or $K(N,\mathfrak p)$ is a prime submodule with $(K(N,\mathfrak p):M)=\mathfrak p$.
\item[(b)] If $P\supseteq N$ is a prime submodule with $(P:M)=\mathfrak p$, then $K(N,\mathfrak p)\subseteq P$. Hence $K(N,\mathfrak p)$ is the smallest prime submodule $P\supseteq N$ with $(P:M)=\mathfrak p$ if such a submodule exists, and $K(N,\mathfrak p)=M$ otherwise.
\end{enumerate}

\label{lem:minprime}
Let $I$ be a radical ideal and $\mathfrak p$ a minimal prime over $I$.
\begin{enumerate}
\item[(a)] For every $a\in\mathfrak p$ there is $t\notin\mathfrak p$ with $ta\in I$.
\item[(b)] If $I$ is real, then $\mathfrak p$ is real.
\end{enumerate}

\label{lem:realbasic}
\begin{enumerate}
\item[(a)] Submodules of real modules are real.
\item[(b)] Direct products, and hence direct sums, of real modules are real.
\item[(c)] Every intersection of real submodules is real.
\item[(d)] Every real module is semiprime; hence every real submodule is semiprime.
\end{enumerate}

\label{prop:realann}
Let $N$ be a submodule of an $R$-module $M$.
\begin{enumerate}
\item[(a)] If $N$ is real, then $(N:m)$ is a real ideal for every $m\in M$.
\item[(b)] If $N$ is semiprime and $(N:m)$ is a real ideal for every $m\in M$, then $N$ is real.
\item[(c)] If $R$ is a Dedekind domain and $(N:m)$ is a real ideal for every $m\in M$, then $N$ is real.
\end{enumerate}

\label{thmC}
For a submodule $N\subseteq R^n$ the following are equivalent:
\begin{enumerate}
\item[(i)] $N$ is real \textup{(}Definition~\ref{def:real}\textup{)};
\item[(ii)] $\sum_if_i\otimes f_i\in R^n\otimes N+N\otimes R^n$ implies $f_i\in N$ for all $i$;
\item[(iii)] $N$ satisfies \textup{(C)}.
\end{enumerate}
